    analyzeBatchFiles() {
      // 分析文件名，配对左右眼图像
      const leftEyes = {};
      const rightEyes = {};
      const paired = [];
      const unpaired = [];

      // 正则表达式匹配ID和左右眼标识
      const regex = /^(\d+)_(left|right)\.(jpg|jpeg|png)/i;
      this.batchFileList.forEach(file => {
        const match = file.name.match(regex);
        if (match) {
          const id = match[1];
          const side = match[2].toLowerCase();
          if (side === "left") {
            leftEyes[id] = file;
          } else if (side === "right") {
            rightEyes[id] = file;
          }
        } else {
          unpaired.push(file);
        }
      });

      // 配对左右眼
      for (const id in leftEyes) {
        if (rightEyes[id]) {
          paired.push({
            id,
            leftEye: leftEyes[id],
            rightEye: rightEyes[id]
          });

          // 从未配对列表中移除已配对的文件
          delete leftEyes[id];
          delete rightEyes[id];
        }
      }

      // 剩余未配对的文件
      for (const id in leftEyes) {
        unpaired.push(leftEyes[id]);
      }
      for (const id in rightEyes) {
        unpaired.push(rightEyes[id]);
      }
      this.pairedImages = paired;
      this.unpairedImages = unpaired;
    },
    // 文件上传前验证
    beforeUpload(file) {
      // 验证文件名是否与选择的患者ID匹配
      if (this.activeTab === "single" && this.selectedPatientId) {
        const fileNameRegex = new RegExp(`^${this.selectedPatientId}`);
        if (!fileNameRegex.test(file.name)) {
          this.$message.warning(`文件名应以患者ID "${this.selectedPatientId}" 开头`);
          return false;
        }
      }
      const isImage = file.type.startsWith("image/");
      const isLt5M = file.size / 1024 / 1024 < 5;
      if (!isImage) {
        this.$message.error("只能上传图片文件!");
        return false;
      }
      if (!isLt5M) {
        this.$message.error("图片大小不能超过 5MB!");
        return false;
      }
      return false; // 阻止自动上传
    },
    // 处理图像
    processSingleImages() {
      if (!this.selectedPatientId) {
        this.$message.warning("请先选择患者");
        return;
      }
      this.processingMode = "single";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;

      // 模拟处理过程
      const timer = setInterval(() => {
        this.processingPercentage += 10;
        if (this.processingPercentage >= 100) {
          clearInterval(timer);
          setTimeout(() => {
            this.processingDialogVisible = false;
            this.generateSingleResult();
            this.updatePatientDiagnosis();
            this.showResults = true;
          }, 500);
        }
      }, 300);
    },
    updatePatientDiagnosis() {
      // 更新患者诊断信息
      if (this.selectedPatientId && this.singleResult) {
        const patientIndex = this.patientList.findIndex(p => p.id === this.selectedPatientId);
        if (patientIndex !== -1) {
          const patient = this.patientList[patientIndex];
          const now = new Date();
          patient.leftEyeDiagnosis = this.singleResult.leftEye.diagnosis;
          patient.leftEyeConfidence = this.singleResult.leftEye.confidence;
          patient.rightEyeDiagnosis = this.singleResult.rightEye.diagnosis;
          patient.rightEyeConfidence = this.singleResult.rightEye.confidence;
          patient.finalDiagnosis = this.singleResult.finalDiagnosis;
          patient.processTime = now.toLocaleString();
          this.$set(this.patientList, patientIndex, patient);
        }
      }
    },
    // 生成结果
    generateSingleResult() {
      // 模拟生成诊断结果
      const leftEyeProbs = this.generateRandomProbabilities();
      const rightEyeProbs = this.generateRandomProbabilities();
      const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
      const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
      this.singleResult = {
        leftEye: {
          diagnosis: this.diseaseCategories[leftMaxIndex],
          confidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
          probabilities: leftEyeProbs
        },
        rightEye: {
          diagnosis: this.diseaseCategories[rightMaxIndex],
          confidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
          probabilities: rightEyeProbs
        },
        finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex),
        suggestion: this.generateSuggestion(leftMaxIndex, rightMaxIndex)
      };

      // 添加到历史记录
      this.addToHistory(this.singleResult);

      // 渲染图表
      this.$nextTick(() => {
        this.renderEyeChart("leftEyeChart", this.singleResult.leftEye.probabilities);
        this.renderEyeChart("rightEyeChart", this.singleResult.rightEye.probabilities);
        this.renderComparisonChart(this.singleResult.leftEye.probabilities, this.singleResult.rightEye.probabilities);
      });
    },
    // 渲染左右眼比较柱状图
    renderComparisonChart(leftEyeProbs, rightEyeProbs) {
      const chartDom = this.$refs.comparisonChart;
      const myChart = echarts.init(chartDom);
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: params => {
            const disease = this.diseaseCategories[params[0].dataIndex];
            let result = `${disease}<br/>`;
            params.forEach(param => {
              const value = param.value;
              result += `${param.seriesName}: ${value}%<br/>`;
            });
            return result;
          }
        },
        legend: {
          data: ["左眼", "右眼"]
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
