          type: "value",
          name: "概率 (%)",
          max: 100
        },
        series: [{
          name: "左眼",
          type: "bar",
          data: leftEyeProbs.map(p => (p * 100).toFixed(1)),
          itemStyle: {
            color: "#409EFF"
          }
        }, {
          name: "右眼",
          type: "bar",
          data: rightEyeProbs.map(p => (p * 100).toFixed(1)),
