    viewHistoryDetail(row) {
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportHistoryReport(row) {
      this.$message.success(`历史记录 ID ${row.id} 的报告已导出为PDF文件`);
    },
    processBatchImages() {
      if (this.selectedPatientIds.length === 0) {
        this.$message.warning("请先选择患者");
        return;
      }
      this.processingMode = "batch";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;
      this.processedCount = 0;
      this.totalProcessCount = this.pairedImages.length;

      // 创建任务队列
      this.taskQueue = this.pairedImages.map((pair, index) => ({
        id: pair.id,
        status: index === 0 ? "processing" : "waiting"
      }));
      this.currentTaskIndex = 0;

      // 模拟批量处理过程
      this.processBatchTask();
    },
    processBatchTask() {
      if (this.currentTaskIndex >= this.taskQueue.length) {
        // 所有任务处理完成
        setTimeout(() => {
          this.processingDialogVisible = false;
          this.generateBatchResults();
          this.updateBatchPatientDiagnosis();
          this.showResults = true;
        }, 500);
        return;
      }
      const task = this.taskQueue[this.currentTaskIndex];
      task.status = "processing";

      // 模拟单个任务处理过程
      let progress = 0;
      const timer = setInterval(() => {
        progress += 20;
        this.processingPercentage = Math.floor((this.processedCount * 100 + progress) / this.totalProcessCount);
        if (progress >= 100) {
          clearInterval(timer);
          task.status = "completed";
          this.processedCount++;
          this.currentTaskIndex++;
          if (this.currentTaskIndex < this.taskQueue.length) {
            this.processBatchTask();
          } else {
            this.processingPercentage = 100;
            setTimeout(() => {
              this.processingDialogVisible = false;
              this.generateBatchResults();
              this.updateBatchPatientDiagnosis();
              this.showResults = true;
            }, 500);
          }
        }
      }, 200);
    },
    updateBatchPatientDiagnosis() {
      // 更新批量患者诊断信息
      if (this.selectedPatientIds.length > 0 && this.batchResults.length > 0) {
        // 根据ID匹配结果和患者
        this.batchResults.forEach(result => {
          const patientId = result.id.split("_")[0]; // 假设格式为 PT2023001_left/right
          if (this.selectedPatientIds.includes(patientId)) {
            const patientIndex = this.patientList.findIndex(p => p.id === patientId);
            if (patientIndex !== -1) {
              const patient = this.patientList[patientIndex];
              const now = new Date();
              patient.leftEyeDiagnosis = result.leftEye.diagnosis;
              patient.leftEyeConfidence = result.leftEye.confidence;
              patient.rightEyeDiagnosis = result.rightEye.diagnosis;
              patient.rightEyeConfidence = result.rightEye.confidence;
              patient.finalDiagnosis = result.finalDiagnosis;
              patient.processTime = now.toLocaleString();
              this.$set(this.patientList, patientIndex, patient);
            }
          }
        });
      }
    },
    getTaskStatusText(status) {
      switch (status) {
        case "waiting":
          return "等待中";
        case "processing":
          return "处理中";
        case "completed":
          return "已完成";
        default:
          return "未知状态";
      }
    },
    percentageFormat(percentage) {
      return percentage + "%";
    },
    // 生成批量结果
    generateBatchResults() {
      // 模拟生成批量诊断结果
      this.batchResults = this.pairedImages.map(pair => {
        const leftEyeProbs = this.generateRandomProbabilities();
        const rightEyeProbs = this.generateRandomProbabilities();
        const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
        const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
        const result = {
          id: pair.id,
          leftEye: {
            diagnosis: this.diseaseCategories[leftMaxIndex],
            confidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
            probabilities: leftEyeProbs
          },
          rightEye: {
            diagnosis: this.diseaseCategories[rightMaxIndex],
            confidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
            probabilities: rightEyeProbs
          },
          finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex),
          suggestion: this.generateSuggestion(leftMaxIndex, rightMaxIndex)
        };

        // 添加到历史记录
        this.addToHistory(result);
        return result;
      });
    },
    // 初始化模拟患者数据
    initPatientData() {
      // 添加一些模拟患者数据
      for (let i = 1; i <= 3; i++) {
        const patientId = `${i}`;
        const gender = Math.random() > 0.5 ? "male" : "female";
        const age = Math.floor(Math.random() * 50) + 20;

        // 随机决定是否已有诊断结果
        const hasDiagnosis = Math.random() > 0.5;
        let diagnosisInfo = {};
        if (hasDiagnosis) {
          const leftEyeProbs = this.generateRandomProbabilities();
          const rightEyeProbs = this.generateRandomProbabilities();
          const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
          const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
          const date = new Date();
          date.setDate(date.getDate() - Math.floor(Math.random() * 10));
          diagnosisInfo = {
            leftEyeDiagnosis: this.diseaseCategories[leftMaxIndex],
            rightEyeDiagnosis: this.diseaseCategories[rightMaxIndex],
            leftEyeConfidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
            rightEyeConfidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
            finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex),
            processTime: date.toLocaleString()
          };
        }
        this.patientList.push({
          id: patientId,
          name: `患者${i}`,
          gender: gender,
          age: age,
          phone: `1381234${i.toString().padStart(4, "0")}`,
          note: "",
          ...diagnosisInfo
        });
      }
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 初始化一些模拟历史记录
    for (let i = 0; i < 5; i++) {
      const leftEyeProbs = this.generateRandomProbabilities();
      const rightEyeProbs = this.generateRandomProbabilities();
      const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
      const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
      const date = new Date();
      date.setDate(date.getDate() - i);
      this.historyRecords.push({
        id: `${i + 10}`,
        // Use a numeric ID
        time: date.toLocaleString(),
        leftEye: {
          diagnosis: this.diseaseCategories[leftMaxIndex],
          confidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
          probabilities: leftEyeProbs
        },
        rightEye: {
          diagnosis: this.diseaseCategories[rightMaxIndex],
          confidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
          probabilities: rightEyeProbs
        },
        finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex)
      });
    }

    // 初始化一些模拟患者数据
    this.initPatientData();
  }
};
